uniform shader src;
uniform float2 res;
uniform float time;
uniform float k;
uniform float seed;
float U(){ return res.x/1080.; }
vec3 S(vec2 uv){ return src.eval(uv*res).rgb; }
float L(vec3 c){ return dot(c, vec3(.299,.587,.114)); }
float h21(vec2 p){ p=fract(p*vec2(123.34,456.21)); p+=dot(p,p+45.32); return fract(p.x*p.y); }
float n21(vec2 p){ vec2 i=floor(p); vec2 f=fract(p); f=f*f*(3.-2.*f);
  return mix(mix(h21(i),h21(i+vec2(1.,0.)),f.x), mix(h21(i+vec2(0.,1.)),h21(i+vec2(1.,1.)),f.x), f.y); }
float b2(vec2 a){ a=floor(a); return fract(a.x/2.+a.y*a.y*.75); }
float bayer(vec2 a){ return b2(.5*a)*.25+b2(a); }
vec3 hue2rgb(float h){ return clamp(abs(fract(h+vec3(0.,.6667,.3333))*6.-3.)-1.,0.,1.); }
float T(float fps){ return floor(time*fps); }
vec2 rot(vec2 p,float a){ float s=sin(a); float c=cos(a); return vec2(p.x*c-p.y*s,p.x*s+p.y*c); }
float edgeAt(vec2 uv,float r){ vec2 d=r*U()/res;
  return length(S(uv+vec2(d.x,0.))-S(uv-vec2(d.x,0.)))+length(S(uv+vec2(0.,d.y))-S(uv-vec2(0.,d.y))); }
// 7-segment digits for date stamps and timecodes (no font needed)
float sg(vec2 p,vec2 a,vec2 b){ vec2 pa=p-a; vec2 ba=b-a; float t=clamp(dot(pa,ba)/dot(ba,ba),0.,1.); return step(length(pa-ba*t),.085); }
float sbit(float m,float i){ return mod(floor(m/exp2(i)),2.); }
float dig(vec2 p,float n){ if(p.x<-.15||p.x>.75||p.y<-.15||p.y>1.15){ return 0.; }
  float m=n<.5?119.:(n<1.5?36.:(n<2.5?93.:(n<3.5?109.:(n<4.5?46.:(n<5.5?107.:(n<6.5?123.:(n<7.5?37.:(n<8.5?127.:111.))))))));
  float r=sbit(m,0.)*sg(p,vec2(0.,0.),vec2(.6,0.))+sbit(m,1.)*sg(p,vec2(0.,0.),vec2(0.,.5))+sbit(m,2.)*sg(p,vec2(.6,0.),vec2(.6,.5))+sbit(m,3.)*sg(p,vec2(0.,.5),vec2(.6,.5))+sbit(m,4.)*sg(p,vec2(0.,.5),vec2(0.,1.))+sbit(m,5.)*sg(p,vec2(.6,.5),vec2(.6,1.))+sbit(m,6.)*sg(p,vec2(0.,1.),vec2(.6,1.));
  return min(r,1.); }
float pw(float h,float c0,float c1,float c2){ float d=fract(h-c1+.5)-.5; return d<0.?max(0.,1.+d/fract(c1-c0)):max(0.,1.-d/fract(c2-c1)); }
float hueOf(vec3 c){ float mx=max(c.r,max(c.g,c.b)); float mn=min(c.r,min(c.g,c.b)); float d=mx-mn; float h=0.; if(d>.0001){ h=mx==c.r?mod((c.g-c.b)/d,6.):(mx==c.g?(c.b-c.r)/d+2.:(c.r-c.g)/d+4.); } return h/6.; }
vec2 AS(){ return vec2(1.,res.y/res.x); }
float num6(vec2 uv,vec2 o,float sz,float a,float b,float c,float sep){ vec2 p=(uv-o)/vec2(sz*res.y/res.x,sz); if(p.x<-.3||p.x>6.8||p.y<-.3||p.y>1.3){ return 0.; }
  float r=0.; for(int i=0;i<3;i++){ float v=floor((i==0?a:(i==1?b:c))+.5); float x=float(i)*2.45; r+=dig(p-vec2(x,0.),floor(v/10.)); r+=dig(p-vec2(x+.95,0.),mod(v,10.)); }
