uniform float aExp;uniform float aCon;uniform float aSat;uniform float aTemp;uniform float aTint;uniform float aHue;uniform float aFade;uniform float aGrain;uniform float aVig;uniform float rMode;uniform float rX;uniform float rY;uniform float rSize;uniform float rFeather;uniform float rAngle;uniform float rInv;/*PRO_DECL*/uniform float u0;uniform float u1;uniform float u2;
